/* IZ tokens → Variables.
 *
 * Reads dist/figma/tokens.json (generated by `npm run build`) and creates, in the open Figma file:
 *   collection "Primitives" — no extra modes, raw values, hidden from publishing
 *   collection "Semantic"   — one mode per theme, every value an ALIAS to a Primitive
 *
 * Idempotent: a second run updates values and aliases instead of creating duplicates, so this is
 * also how a token change reaches Figma (docs/decisions.md ADR-004: Git is canonical).
 *
 * Install: Figma → Plugins → Development → Import plugin from manifest… → tools/figma-plugin/manifest.json
 */

const VENDOR = 'design.iz.figma';

/** DTCG value → Figma variable value, plus the Figma resolvedType it needs. */
function toFigma(type, value) {
  switch (type) {
    case 'color': {
      const [r, g, b] = value.components;
      return { resolvedType: 'COLOR', value: { r, g, b, a: 1 } };
    }
    case 'dimension': {
      // Figma numbers are unitless px. rem is 16 px here; em (letter-spacing) becomes a percentage.
      if (value.unit === 'rem') return { resolvedType: 'FLOAT', value: value.value * 16 };
      if (value.unit === 'em') return { resolvedType: 'FLOAT', value: value.value * 100, note: 'em → percent' };
      return { resolvedType: 'FLOAT', value: value.value };
    }
    case 'duration':
      return { resolvedType: 'FLOAT', value: value.unit === 's' ? value.value * 1000 : value.value };
    case 'number':
    case 'fontWeight':
      return { resolvedType: 'FLOAT', value };
    case 'fontFamily':
      return { resolvedType: 'STRING', value: Array.isArray(value) ? value[0] : value };
    default:
      // cubicBezier, shadow, typography: Figma has no variable type for these.
      return null;
  }
}

async function getCollection(name) {
  const existing = await figma.variables.getLocalVariableCollectionsAsync();
  const found = existing.find((c) => c.name === name);
  return found || figma.variables.createVariableCollection(name);
}

/**
 * Make the collection's modes exactly `names`, in order, reusing the default mode for the first.
 * Figma caps modes per plan — Starter has none, Professional allows 10 — and addMode throws when
 * the cap is reached. Degrade instead of failing: import the modes that fit, report the rest, and
 * let a later run on a higher plan fill them in (this plugin is idempotent).
 */
function syncModes(collection, names) {
  collection.renameMode(collection.modes[0].modeId, names[0]);
  const refused = [];
  for (const name of names.slice(1)) {
    if (collection.modes.some((m) => m.name === name)) continue;
    try {
      collection.addMode(name);
    } catch {
      // Figma throws when the plan's mode cap is reached; which modes were refused is the useful part.
      refused.push(name);
    }
  }
  const byName = {};
  for (const m of collection.modes) byName[m.name] = m.modeId;
  return { byName, refused };
}

async function variableIndex(collection) {
  const all = await figma.variables.getLocalVariablesAsync();
  const index = {};
  for (const v of all) if (v.variableCollectionId === collection.id) index[v.name] = v;
  return index;
}

function ensureVariable(index, name, collection, resolvedType) {
  const existing = index[name];
  // A variable cannot change type; a type change means the token changed and the old one must go.
  if (existing && existing.resolvedType !== resolvedType) {
    existing.remove();
    delete index[name];
  }
  if (!index[name]) index[name] = figma.variables.createVariable(name, collection, resolvedType);
  return index[name];
}

/** Refuse anything that is not dist/figma/tokens.json, by name, instead of importing nothing. */
function assertShape(doc) {
  if (!doc || typeof doc !== 'object') throw new Error('That file is not a JSON object.');
  const hasCollections = doc.Primitives && doc.Semantic;
  const hasMeta = (doc.$extensions || {})[VENDOR];
  if (hasCollections && hasMeta) return;
  const keys = Object.keys(doc).filter((k) => k !== '$description').slice(0, 6).join(', ') || '(none)';
  const guess = doc.themes
    ? '\n\nThis looks like docs/specs/tokens.dtcg.json — a different generated file, keyed by theme.'
    : '';
  throw new Error(
    `This is not the Figma export.\n\nExpected top-level "Primitives" and "Semantic" plus ` +
    `$extensions["${VENDOR}"].\nFound: ${keys}.${guess}\n\nPick dist/figma/tokens.json ` +
    `(run "npm run build" if it is missing).`
  );
}

async function importTokens(doc) {
  assertShape(doc);
  const meta = (doc.$extensions || {})[VENDOR] || {};
  const collections = meta.collections || [];
  const semanticMeta = collections.find((c) => c.name === 'Semantic') || {};
  const modeNames = semanticMeta.modes && semanticMeta.modes.length ? semanticMeta.modes : ['light'];

  const report = [];
  const skipped = [];
  const notes = new Set();

  // ── Primitives first: the Semantic aliases point at them.
  const primitives = await getCollection('Primitives');
  primitives.hiddenFromPublishing = true;
  const primitiveMode = primitives.modes[0].modeId;
  const primitiveIndex = await variableIndex(primitives);
  let primitiveCount = 0;

  for (const [name, token] of Object.entries(doc.Primitives || {})) {
    const mapped = toFigma(token.$type, token.$value);
    if (!mapped) { skipped.push(`${name} (${token.$type} has no Figma variable type)`); continue; }
    if (mapped.note) notes.add(mapped.note);
    const variable = ensureVariable(primitiveIndex, name, primitives, mapped.resolvedType);
    variable.setValueForMode(primitiveMode, mapped.value);
    if (token.$description) variable.description = token.$description;
    primitiveCount++;
  }
  report.push(`Primitives: ${primitiveCount} variables, 1 mode, hidden from publishing`);

  // ── Semantic: one mode per theme, every value an alias.
  const semantic = await getCollection('Semantic');
  const { byName: modeIds, refused } = syncModes(semantic, modeNames);
  const imported = modeNames.filter((m) => modeIds[m]);
  const semanticIndex = await variableIndex(semantic);
  let semanticCount = 0;
  let aliasCount = 0;
  const unresolved = [];

  for (const [name, token] of Object.entries(doc.Semantic || {})) {
    const modes = ((token.$extensions || {})[VENDOR] || {}).modes || {};
    const probe = toFigma(token.$type, token.$value);
    if (!probe) { skipped.push(`${name} (${token.$type} has no Figma variable type)`); continue; }
    const variable = ensureVariable(semanticIndex, name, semantic, probe.resolvedType);
    if (token.$description) variable.description = token.$description;

    for (const [modeName, entry] of Object.entries(modes)) {
      const modeId = modeIds[modeName];
      if (!modeId) continue; // refused by the plan — reported once below, not per variable
      const target = primitiveIndex[entry.alias];
      if (target) {
        variable.setValueForMode(modeId, figma.variables.createVariableAlias(target));
        aliasCount++;
      } else {
        // No primitive of that name: fall back to the resolved value so nothing is silently empty.
        const mapped = toFigma(token.$type, entry.resolved);
        if (mapped) variable.setValueForMode(modeId, mapped.value);
        unresolved.push(`${name} [${modeName}]: primitive "${entry.alias}" not found — raw value set instead`);
      }
    }
    semanticCount++;
  }
  report.push(`Semantic: ${semanticCount} variables × ${imported.length} mode(s) (${imported.join(', ')}), ${aliasCount} aliases`);
  if (refused.length) {
    report.push(
      `\nFigma refused ${refused.length} mode(s): ${refused.join(', ')}.\n` +
      'Variable modes are a paid feature: Starter has none, Professional allows 10. Everything that\n' +
      'fits was imported. Re-run this plugin after upgrading and the missing modes fill in — it\n' +
      'updates in place, nothing is duplicated.'
    );
  }

  if (notes.size) report.push(`Conversions: ${[...notes].join('; ')}`);
  if (skipped.length) report.push(`\nSkipped ${skipped.length} (expected — no Figma type):\n  ${skipped.join('\n  ')}`);
  if (unresolved.length) report.push(`\n${unresolved.length} problem(s):\n  ${unresolved.join('\n  ')}`);
  else if (imported.length > 1) report.push('\nEvery Semantic value is an alias. Switch the Semantic mode to check the mirror.');
  else report.push('\nEvery Semantic value is an alias, but only one mode exists — the mirror cannot be checked by switching modes yet.');

  return report.join('\n');
}

figma.showUI(__html__, { width: 380, height: 420 });

figma.ui.onmessage = async (msg) => {
  if (msg.type !== 'import') return;
  try {
    const report = await importTokens(msg.payload);
    figma.ui.postMessage({ ok: true, report });
    figma.notify('IZ tokens imported');
  } catch (error) {
    figma.ui.postMessage({ ok: false, report: `${error.message}\n\n${error.stack || ''}` });
    figma.notify('Import failed — see the plugin panel', { error: true });
  }
};
